// A variable holds a value. A conditional picks a branch each frame.
let size = 60;

function setup() {
  createCanvas(400, 400);
}

function draw() {
  background(240);
  let x = mouseX;                       // read the mouse every frame
  if (x < width / 2) {
    fill(200, 60, 60);                  // left half: red
  } else {
    fill(60, 60, 200);                  // right half: blue
  }
  ellipse(x, height / 2, size);
}

// A loop repeats a step. A nested loop visits every cell of a grid.
function setup() {
  createCanvas(400, 400);
  noStroke();
}

function draw() {
  background(255);
  let cell = int(map(mouseX, 0, width, 10, 80));   // mouse sets the cell size
  for (let row = 0; row * cell < height; row++) {
    for (let col = 0; col * cell < width; col++) {
      if ((row + col) % 2 === 0) {
        fill(30);
      } else {
        fill(230);
      }
      rect(col * cell, row * cell, cell, cell);
    }
  }
}

// A function names a step so you can reuse it.
function drawDot(x, y, r, c) {
  fill(c);
  ellipse(x, y, r * 2);
}

// A function can also return a value.
function avgBright(c) {
  return (red(c) + green(c) + blue(c)) / 3;
}

function setup() {
  createCanvas(400, 400);
  noStroke();
}

function draw() {
  background(250);
  for (let i = 0; i < 8; i++) {
    let c = color(i * 30, 120, 255 - i * 30);
    let x = 50 + i * 40;
    let y = 200 + sin(frameCount * 0.05 + i) * 80;
    drawDot(x, y, 10 + avgBright(c) / 20, c);
  }
}

// A class bundles data (position, speed) with behaviour (update, show).
class Walker {
  constructor(x, y, c) {
    this.x = x;
    this.y = y;
    this.vx = random(-2, 2);
    this.vy = random(-2, 2);
    this.c = c;
  }

  update() {                              // runs once per frame
    this.x += this.vx;
    this.y += this.vy;
    if (this.x < 0 || this.x > width) this.vx *= -1;    // bounce off the sides
    if (this.y < 0 || this.y > height) this.vy *= -1;
  }

  show() {
    fill(this.c);
    ellipse(this.x, this.y, 30);
  }
}

let walkers = [];

function setup() {
  createCanvas(400, 400);
  for (let i = 0; i < 8; i++) {
    walkers.push(new Walker(random(width), random(height), color(random(255), 120, 200)));
  }
}

function draw() {
  background(245);
  for (let w of walkers) {
    w.update();
    w.show();
  }
}

// Algorithm: linear search. Check every point and keep the best so far.
let pts = [];

function setup() {
  createCanvas(400, 400);
  for (let i = 0; i < 40; i++) {
    pts.push(createVector(random(width), random(height)));
  }
}

function draw() {
  background(245);
  let m = createVector(mouseX, mouseY);
  let best = null;
  let bestD = Infinity;

  for (let p of pts) {
    noStroke();
    fill(120);
    ellipse(p.x, p.y, 8);
    let d = p5.Vector.dist(m, p);         // distance from the mouse to this point
    if (d < bestD) {                      // keep the closest so far
      bestD = d;
      best = p;
    }
  }

  stroke(200, 40, 40);
  strokeWeight(2);
  line(mouseX, mouseY, best.x, best.y);
  noStroke();
  fill(200, 40, 40);
  ellipse(best.x, best.y, 14);
}

// map() rescales a value from one range to another.
// lerp() moves a fraction of the way from a to b: easing.
let x = 200;

function setup() {
  createCanvas(400, 400);
  textSize(14);
}

function draw() {
  background(245);
  x = lerp(x, mouseX, 0.08);              // ease 8% of the way each frame
  let hue = map(x, 0, width, 0, 255);     // rescale 0..400 to 0..255
  noStroke();
  fill(0);
  ellipse(mouseX, 90, 10);                // the target
  fill(hue, 90, 220);
  ellipse(x, height / 2, 80);             // the eased position
  fill(40);
  text('mapped value: ' + nf(hue, 1, 0), 16, 30);
}

// Pixels are an array: four numbers per pixel (red, green, blue, alpha).
// Index = 4 * (x + y * width).
function setup() {
  createCanvas(300, 300);
  pixelDensity(1);                        // one canvas pixel per array entry
}

function draw() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let i = 4 * (x + y * width);
      let d = dist(x, y, mouseX, mouseY);
      let v = constrain(map(d, 0, 200, 255, 0), 0, 255);  // closer = brighter
      pixels[i]     = v;                  // red
      pixels[i + 1] = x * 255 / width;    // green rises left to right
      pixels[i + 2] = y * 255 / height;   // blue rises top to bottom
      pixels[i + 3] = 255;                // alpha: fully opaque
    }
  }
  updatePixels();
}

// A vector has a direction and a length.
function setup() {
  createCanvas(400, 400);
  textSize(14);
}

function draw() {
  background(245);
  let center = createVector(width / 2, height / 2);
  let m = createVector(mouseX, mouseY);
  let dir = p5.Vector.sub(m, center);     // vector from the centre to the mouse
  let len = dir.mag();                    // its length
  let angle = dir.heading();              // its direction, in radians

  // local coordinates: move the origin to the centre, then turn
  push();
  translate(center.x, center.y);
  rotate(angle);
  stroke(40);
  strokeWeight(3);
  line(0, 0, len, 0);                     // arrow along the local x-axis
  pop();

  // normalise to length 1, then scale to 60 and step out from the centre
  let tip = p5.Vector.add(center, dir.copy().normalize().mult(60));
  noStroke();
  fill(200, 40, 40);
  ellipse(tip.x, tip.y, 12);
  fill(40);
  text('length: ' + nf(len, 1, 0), 16, 24);
}

// 3D is the same loop with a third axis. WEBGL mode turns it on.
function setup() {
  createCanvas(400, 400, WEBGL);
}

function draw() {
  background(245);
  orbitControl();                         // drag to orbit the camera
  rotateY(frameCount * 0.005);            // turn the whole scene
  noStroke();
  for (let gx = -2; gx <= 2; gx++) {
    for (let gz = -2; gz <= 2; gz++) {
      let h = noise(gx * 0.5 + 10, gz * 0.5, frameCount * 0.01) * 150 + 10;
      push();
      translate(gx * 50, 0, gz * 50);
      fill(60 + h, 120, 200);
      box(40, h, 40);
      pop();
    }
  }
}

// A signal is a stream of samples. Keep a history and draw it.
let raw = [];
let smooth = [];
let s = 0;

function setup() {
  createCanvas(400, 400);
  textSize(14);
}

function draw() {
  background(245);
  let sample = noise(frameCount * 0.02) * height;   // stand-in for a sensor
  s = lerp(s, sample, 0.1);                         // a simple smoothing filter
  raw.push(sample);
  smooth.push(s);
  if (raw.length > width) {               // keep only the last 400 samples
    raw.shift();
    smooth.shift();
  }

  noFill();
  stroke(170);
  strokeWeight(1);
  beginShape();
  for (let i = 0; i < raw.length; i++) vertex(i, height - raw[i]);
  endShape();

  stroke(200, 40, 40);
  strokeWeight(2);
  beginShape();
  for (let i = 0; i < smooth.length; i++) vertex(i, height - smooth[i]);
  endShape();

  noStroke();
  fill(120);
  text('grey: raw   red: smoothed', 12, 22);
}

// A system: many simple objects, each with forces, updated every frame.
let parts = [];
const gravity = 0.15;                     // a force applied every frame

class Particle {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(1, 4));
    this.life = 255;
  }

  update() {
    this.vel.add(createVector(0, gravity));   // force changes velocity
    this.pos.add(this.vel);                   // velocity changes position
    this.life -= 3;                           // fade out
  }

  show() {
    noStroke();
    fill(220, 80, 60, this.life);
    ellipse(this.pos.x, this.pos.y, 10);
  }

  dead() {
    return this.life <= 0;
  }
}

function setup() {
  createCanvas(400, 400);
  textSize(14);
}

function draw() {
  noStroke();
  fill(30, 30, 40, 40);                   // translucent wash leaves trails
  rect(0, 0, width, height);
  if (mouseIsPressed) {
    for (let i = 0; i < 3; i++) parts.push(new Particle(mouseX, mouseY));
  }
  for (let p of parts) {
    p.update();
    p.show();
  }
  parts = parts.filter(p => !p.dead());  // drop particles that have faded
  fill(255);
  text('particles: ' + parts.length, 10, 20);
}

